CREATE PROCEDURE rep.[999_adf_DWH_fixed_countrycurrencylist] AS
BEGIN


-- Drop existing [DWH_geography] table if it exists
IF OBJECT_ID('stg.fixed_countrycurrencylist', 'U') IS NOT NULL
Drop Table stg.fixed_countrycurrencylist;
		
CREATE TABLE stg.fixed_countrycurrencylist (

    Entity varchar(255),
    Currency varchar(255),
    AlphabeticCode varchar(20),
    NumericCode INTEGER,
    MinorUnit INTEGER,
    WithdrawalDate varchar(20)
);

-- select * from stg.fixed_countrycurrencylist order by 1 asc
-- PALESTINE ', ' STATE OF
END